package com.refind.service.impl;
import com.refind.dao.NotificationDAO; import com.refind.exception.ValidationException; import com.refind.model.Notification; import com.refind.service.NotificationService; import java.util.*;
public class JdbcNotificationService implements NotificationService { private final NotificationDAO dao; public JdbcNotificationService(NotificationDAO dao){this.dao=dao;} public Notification createNotification(Notification n){if(n==null||n.getUser()==null||n.getUser().getId()==null)throw new ValidationException("Notification user is required.");if(n.getText()==null||n.getText().isBlank())throw new ValidationException("Notification text is required.");return dao.save(n);} public Optional<Notification> getNotificationById(Long id){return dao.findById(id);} public List<Notification> getNotificationsByUser(Long id){return dao.findByUser(id);} public List<Notification> getUnreadNotifications(Long id){return dao.findUnreadByUser(id);} public boolean markAsRead(Long id){return dao.markAsRead(id);} public boolean deleteNotification(Long id){return dao.deleteById(id);} }
